def investigate(context, acquire):
    def feed(state, data):
        if state[1] != 'open':
            return
        pending = state[0]
        stream = pending + list(data)
        state[0] = []
        index = 0
        total = len(stream)
        while index < total:
            lead = stream[index]
            if lead < 128:
                state[2] += 1
                index += 1
            elif lead < 192:
                state[1] = 'error'
                return
            elif lead < 224:
                size = 2
                low = 128
                high = 191
            elif lead < 240:
                size = 3
                if lead < 226:
                    low = 160
                elif lead < 237:
                    low = 128
                elif lead == 237:
                    low = 128
                    high = 159
                else:
                    low = 128
            else:
                if lead > 244:
                    state[1] = 'error'
                    return
                size = 4
                if lead == 240:
                    low = 144
                elif lead < 244:
                    low = 128
                else:
                    low = 128
                    high = 143
            if index + size > total:
                state[0] = stream[index:]
                return
            valid = True
            for offset in range(1, size):
                byte = stream[index + offset]
                if byte < low or byte > high:
                    valid = False
                    break
            if not valid:
                state[1] = 'error'
                return
            state[2] += 1
            index += size

    def finish(state):
        if state[1] != 'open':
            return
        if len(state[0]) != 0:
            state[1] = 'error'
        else:
            state[1] = 'finished'

    state = [[], 'open', 0]
    for event in context['events']:
        op = event['op']
        if op == 'feed':
            feed(state, event['bytes'])
        elif op == 'finish':
            finish(state)
        elif op == 'reset':
            state[0] = []
            state[1] = 'open'
            state[2] = 0
    return {'count': state[2], 'status': state[1]}
